import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

import org.springframework.stereotype.Service;

/**
 * Holds every message sent in this application, so the list survives leaving and coming back to the view.
 */
@Service
public class ContactMessageStore {

    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();

    public void add(ContactMessage message) {
        messages.add(0, message);
    }

    /**
     * @return all sent messages, newest first
     */
    public List<ContactMessage> getAll() {
        return List.copyOf(messages);
    }
}
